1151	///|
1152	fn diagnostic_partial_secret(text : String, secrets : Array[String]) -> String {
1153	  let chars = text.iter().to_array()
1154	  let mut boundary = chars.length()
1155	  for secret in secrets {
1156	    let value = secret.iter().to_array()
1157	    if value.length() == 0 || text.has_suffix(secret) {
1158	      continue
1159	    }
1160	    let limit = if value.length() - 1 < boundary {
1161	      value.length() - 1
1162	    } else {
1163	      boundary
1164	    }
1165	    if limit == 0 {
1166	      continue
1167	    }
1168	    let prefixes = FixedArray::make(limit, 0)
1169	    let mut matched = 0
1170	    for index in 1..<limit {
1171	      while matched > 0 && value[matched] != value[index] {
1172	        matched = prefixes[matched - 1]
1173	      }
1174	      if value[matched] == value[index] {
1175	        matched += 1
1176	      }
1177	      prefixes[index] = matched
1178	    }
1179	    matched = 0
1180	    for index in 0..<boundary {
1181	      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
1182	        matched = prefixes[matched - 1]
1183	      }
1184	      if matched < limit && value[matched] == chars[index] {
1185	        matched += 1
1186	      }
1187	    }
1188	    boundary -= matched
1189	  }
1190	  if boundary == chars.length() {
1191	    text
1192	  } else {
1193	    character_text(chars, 0, boundary) + "[redacted]"
1194	  }
1195	}
