1204	///|
1205	fn diagnostic_add_protected(
1206	  value : String,
1207	  output : String,
1208	  uncertain : Bool,
1209	  destination : Array[String],
1210	  result : DiagnosticProtectedValues,
1211	) -> Unit {
1212	  if value == "" ||
1213	    (
1214	      !output.contains(value) &&
1215	      (!uncertain || diagnostic_partial_secret(output, [value]) == output)
1216	    ) {
1217	    return
1218	  }
1219	  if result.secrets.length() >= 512 {
1220	    result.incomplete = true
1221	    return
1222	  }
1223	  destination.push(value)
1224	}
