1336	///|
1337	fn diagnostic_output(
1338	  output : Bytes,
1339	  environment : Map[String, String],
1340	  protected_input? : String,
1341	  protect_all_input~ : Bool = false,
1342	  protected_secrets? : Array[String],
1343	  omitted~ : Bool = false,
1344	) -> String? {
1345	  if output.length() == 0 {
1346	    return if omitted {
1347	      Some("[error details incomplete or truncated]")
1348	    } else {
1349	      None
1350	    }
1351	  }
1352	  let limit = if output.length() > 8192 { 8192 } else { output.length() }
1353	  let incomplete = omitted || limit < output.length()
1354	  let text = @utf8.decode_lossy(output[:limit])
1355	  let safeguards : DiagnosticProtectedValues = {
1356	    secrets: [],
1357	    visited: 0,
1358	    incomplete: false,
1359	  }
1360	  if protected_input is Some(input) {
1361	    diagnostic_protected_values(
1362	      @json.parse(input),
1363	      safeguards,
1364	      text,
1365	      incomplete,
1366	      secret=protect_all_input,
1367	    ) catch {
1368	      _ => safeguards.incomplete = true
1369	    }
1370	  }
1371	  if safeguards.incomplete {
1372	    return Some(
1373	      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
1374	    )
1375	  }
1376	  Some(
1377	    diagnostic_text(
1378	      text,
1379	      environment~,
1380	      omitted=incomplete,
1381	      protected_secrets=safeguards.secrets + protected_secrets.unwrap_or([]),
1382	      incomplete_final_line=incomplete && output[limit - 1] != b'\n',
1383	    ),
1384	  )
1385	}
