171	  protection_incomplete~ : Bool = false,
172	) -> Progress {
173	  let secrets = []
174	  for name, value in environment.unwrap_or(@env.get_env_vars()) {
175	    if sensitive_name(name) && value != "" {
176	      // Multiline credentials must also be masked in line-oriented output.
177	      add_protected_secret(secrets, value)
178	    }
179	  }
180	  if protected_secrets is Some(values) {
181	    for value in values {
182	      add_protected_secret(secrets, value)
183	    }
184	  }
185	  secrets.sort_by((a, b) => b.length().compare(a.length()))
186	  {
187	    stage,
188	    operations: {},
189	    builds: {},
190	    secrets,
191	    protection_incomplete,
192	    recording: recording_override.unwrap_or(
193	      environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
194	      Some("0"),
195	    ),
196	    context,
197	    phase_count: 0,
198	    private_key: false,
199	    classic_build: false,
200	    recent: [],
201	    failures: [],
202	    unrecognized: [],
