310	///|
311	async fn Progress::status(self : Progress, event : Json) -> Unit {
312	  guard field(event, "phase") is Some(Json::String(phase)) &&
313	    phase_label(phase) is Some(label) &&
314	    field(event, "state") is Some(Json::String(state)) &&
315	    ["started", "succeeded", "failed", "skipped"].contains(state) else {
316	    return
317	  }
318	  if self.phase_count < 128 {
319	    self.phase_count += 1
320	    save_diagnostic(
321	      self.stage,
322	      state,
323	      phase~,
324	      error_type?=if state == "failed" { Some("backend_phase") } else { None },
325	      evidence?=self.context,
326	      evidence_stable_operation=true,
327	      protected_secrets=self.secrets,
328	      recording=self.recording,
329	    )
330	  } else if self.phase_count == 128 {
331	    self.phase_count += 1
332	    self.details_truncated = true
333	    save_diagnostic(
334	      self.stage,
335	      "diagnostics-truncated",
336	      error_type="phase_limit",
337	      phase~,
338	      evidence?=self.context,
339	      evidence_incomplete=true,
340	      evidence_stable_operation=true,
341	      protected_secrets=self.secrets,
342	      recording=self.recording,
343	    )
344	  }
345	  let key = ["pipeline", "operationId", "phase", "step"]
346	    .map(name => field(event, name).unwrap_or(Json::null()).stringify())
347	    .join(":")
348	  if state == "started" {
349	    if self.operations.length() >= 256 {
350	      self.operations.clear()
351	    }
352	    self.operations.set(key, @env.now())
353	    progress_message(label + ": running…")
354	  } else {
355	    let duration = match field(event, "durationMs") {
356	      Some(Json::Number(value, ..)) if value >= 0 && value < 864000000 =>
357	        Some(seconds(value.to_uint64()))
358	      _ => self.operations.get(key).map(start => seconds(@env.now() - start))
359	    }
360	    self.operations.remove(key)
361	    let timing = duration.map(value => value + ", ").unwrap_or("") +
362	      "elapsed " +
363	      seconds(@env.now() - progress_started)
364	    progress_message(
365	      label +
366	      ": " +
367	      (if state == "succeeded" { "done" } else { state }) +
368	      " (" +
369	      timing +
370	      ")",
371	    )
372	  }
373	}
