375	///|
376	fn classic_build_step(text : String) -> Bool {
377	  guard text.has_prefix("Step ") &&
378	    text[5:].split_once("/") is Some((step, rest)) &&
379	    rest.split_once(" ") is Some((total, detail)) else {
380	    return false
381	  }
382	  step.length() > 0 &&
383	  total.length() > 0 &&
384	  step.iter().all(c => c >= '0' && c <= '9') &&
385	  total.iter().all(c => c >= '0' && c <= '9') &&
386	  detail.trim().has_prefix(":")
387	}
