487	///|
488	fn progress_json_text(text : String, truncated : Ref[Bool]) -> String {
489	  if !text.contains("\u001b") {
490	    return text
491	  }
492	  let parts : Array[String] = []
493	  for line in text.split("\n") {
494	    match terminal_text(line.to_owned()) {
495	      Some(safe) => parts.push(safe)
496	      None => {
497	        truncated.val = true
498	        return "[unavailable]"
499	      }
500	    }
501	  }
502	  parts.join("\n")
503	}
