590	  let event = @json.parse(line) catch { _ => Json::null() }
591	  if field(event, "kind") == Some(Json::string("status")) {
592	    if field(event, "state") == Some(Json::string("failed")) &&
593	      field(event, "error") is Some(error) {
594	      for name in ["message", "hint"] {
595	        if field(error, name) is Some(Json::String(text)) {
596	          self.message(
597	            text,
598	            debug=false,
599	            warning=true,
600	            emit=messages || statuses,
601	          )
602	        }
603	      }
604	      self.remember_unrecognized_json(event)
605	    }
606	    if statuses || messages {
607	      self.status(event)
608	    }
609	    return
610	  }
611	  // Result envelopes and arbitrary structured responses are never log text.
612	  if field(event, "kind") == Some(Json::string("result")) {
613	    if field(event, "outcome") != Some(Json::string("success")) &&
614	      (
615	        field(event, "error") is Some(_) ||
616	        field(event, "message") is Some(_) ||
617	        field(event, "code") is Some(_) ||
618	        field(event, "outcome") == Some(Json::string("failure")) ||
619	        field(event, "outcome") == Some(Json::string("error"))
620	      ) {
621	      self.remember_unrecognized_json(event)
622	    }
623	    return
624	  }
625	  if field(event, "kind") == Some(Json::string("orca-env-devsy-server-exit")) {
626	    return
627	  }
628	  if event is Json::Object(_) {
629	    let kind = field(event, "kind")
630	    guard kind == None ||
631	      kind == Some(Json::string("log")) ||
632	      kind == Some(Json::string("error")) else {
633	      self.remember_unrecognized_json(event)
634	      return
635	    }
636	    let message = match field(event, "msg") {
637	      Some(value) => Some(value)
638	      None =>
639	        match field(event, "message") {
640	          Some(value) => Some(value)
641	          None =>
642	            match field(event, "error") {
643	              Some(Json::Object(_) as value) => field(value, "message")
644	              value => value
645	            }
646	        }
647	    }
648	    guard message is Some(Json::String(text)) else {
649	      self.remember_unrecognized_json(event)
650	      return
651	    }
652	    let level = field(event, "level")
653	    self.message(
654	      text,
655	      debug=level == Some(Json::string("debug")) ||
656	        level == Some(Json::string("trace")),
657	      warning=kind == Some(Json::string("error")) ||
658	        level == Some(Json::string("warn")) ||
659	        level == Some(Json::string("error")),
660	      emit=messages || (statuses && kind != None),
661	    )
662	  } else {
663	    if event != Json::null() {
664	      self.remember_unrecognized_json(event)
665	      return
666	    }
667	    // Malformed JSON and binary output are not a safe free-text fallback.
668	    let text = line.trim().to_owned()
669	    if text.has_prefix("[ERROR]") || text.has_prefix("[WARN]") {
670	      self.message(text, debug=false, warning=true, emit=messages)
671	      return
672	    }
673	    if text.has_prefix("{") || text.has_prefix("[") {
674	      self.details_truncated = true
675	      self.remember_unrecognized(text)
676	      return
677	    }
678	    self.message(
679	      text,
680	      debug=text.contains(" DEBUG ") ||
681	        text.contains(" TRACE ") ||
682	        text.has_prefix("DEBUG ") ||
683	        text.has_prefix("TRACE "),
684	      warning=text.contains(" WARN ") ||
685	        text.contains(" ERROR ") ||
686	        text.has_prefix("WARN ") ||
687	        text.has_prefix("ERROR "),
688	      emit=messages,
689	    )
690	  }
691	}
