1115	  let mut incomplete = omitted
1116	  let source_lines = message.split("\n").to_array()
1117	  for index in 0..<source_lines.length() {
1118	    let line = source_lines[index]
1119	    if lines.length() == 32 {
1120	      incomplete = true
1121	      ignore(lines.remove(1))
1122	    }
1123	    let truncated = line.length() > 1024
1124	    let bounded = if truncated {
1125	      incomplete = true
1126	      line[:1024].to_owned()
1127	    } else {
1128	      line.to_owned()
1129	    }
1130	    let bounded = if truncated ||
1131	      (incomplete_final_line && index == source_lines.length() - 1) {
1132	      diagnostic_partial_secret(bounded, progress.secrets)
1133	    } else {
1134	      bounded
1135	    }
1136	    match progress.safe_message(bounded) {
