1226	///|
1227	fn diagnostic_protected_values(
1228	  value : Json,
1229	  result : DiagnosticProtectedValues,
1230	  output : String,
1231	  uncertain : Bool,
1232	  secret~ : Bool = false,
1233	  depth~ : Int32 = 0,
1234	) -> Unit {
1235	  if result.visited >= 65536 || depth >= 64 {
1236	    result.incomplete = true
1237	    return
1238	  }
1239	  result.visited += 1
1240	  match value {
1241	    Json::String(text) if text != "" && secret => {
1242	      let destination = result.secrets
1243	      diagnostic_add_protected(text, output, uncertain, destination, result)
1244	      for line in text.split("\n") {
1245	        if line != "" && line.length() < text.length() {
1246	          diagnostic_add_protected(
1247	            line.to_owned(),
1248	            output,
1249	            uncertain,
1250	            destination,
1251	            result,
1252	          )
1253	        }
1254	        for word in line.split(" ") {
1255	          for part in word.split("=") {
1256	            if part != "" && part.length() < text.length() {
1257	              diagnostic_add_protected(
1258	                part.to_owned(),
1259	                output,
1260	                uncertain,
1261	                destination,
1262	                result,
1263	              )
1264	            }
1265	          }
1266	        }
1267	      }
1268	      let escaped = Json::string(text).stringify()
1269	      if escaped.length() > 2 {
1270	        let encoded = escaped[1:escaped.length() - 1].to_owned()
1271	        if encoded != text {
1272	          diagnostic_add_protected(
1273	            encoded, output, uncertain, destination, result,
1274	          )
1275	        }
1276	      }
1277	    }
1278	    Json::String(text) if text != "" => {
1279	      let mut next_secret = false
1280	      for word in text.split(" ") {
1281	        let word = word.to_owned()
1282	        if next_secret {
1283	          diagnostic_add_protected(
1284	            word,
1285	            output,
1286	            uncertain,
1287	            result.secrets,
1288	            result,
1289	          )
1290	          next_secret = false
1291	        } else if word.split_once("=") is Some((name, value)) {
1292	          if credential_field(name.to_owned(), for_diagnostics=true) {
1293	            diagnostic_add_protected(
1294	              value.to_owned(),
1295	              output,
1296	              uncertain,
1297	              result.secrets,
1298	              result,
1299	            )
1300	          }
1301	        } else if word.has_prefix("-") &&
1302	          credential_field(word, for_diagnostics=true) {
1303	          next_secret = true
1304	        }
1305	      }
1306	    }
1307	    Json::Array(values) =>
1308	      for item in values {
1309	        diagnostic_protected_values(
1310	          item,
1311	          result,
1312	          output,
1313	          uncertain,
1314	          secret~,
1315	          depth=depth + 1,
1316	        )
1317	      }
1318	    Json::Object(values) =>
1319	      for name, item in values {
1320	        let key = name.to_lower().replace_all(old="_", new="")
1321	        diagnostic_protected_values(
1322	          item,
1323	          result,
1324	          output,
1325	          uncertain,
1326	          secret=secret ||
1327	            credential_field(name, for_diagnostics=true) ||
1328	            key == "pairingcode",
1329	          depth=depth + 1,
1330	        )
1331	      }
1332	    _ => ()
1333	  }
1334	}
