   505	///|
   506	fn progress_normalize_json(
   507	  value : Json,
   508	  truncated : Ref[Bool],
   509	  depth : Int32,
   510	) -> Json {
   511	  if depth >= 64 {
   512	    truncated.val = true
   513	    return Json::string("[unavailable]")
   514	  }
   515	  match value {
   516	    Json::String(text) => Json::string(progress_json_text(text, truncated))
   517	    Json::Array(values) =>
   518	      Json::array(
   519	        values.map(item => progress_normalize_json(item, truncated, depth + 1)),
   520	      )
   521	    Json::Object(values) => {
   522	      let result = Json::empty_object()
   523	      for name, item in values {
   524	        let key = progress_json_text(name, truncated)
   525	        if field(result, key) is Some(_) {
   526	          truncated.val = true
   527	        } else {
   528	          set_field(
   529	            result,
   530	            key,
   531	            progress_normalize_json(item, truncated, depth + 1),
   532	          )
   533	        }
   534	      }
   535	      result
   536	    }
   537	    _ => value
   538	  }
   539	}
