   581	async fn Progress::line(
   582	  self : Progress,
   583	  line : String,
   584	  statuses~ : Bool,
   585	  messages~ : Bool,
   586	) -> Unit {
   587	  if line.trim() == "" {
   588	    return
   589	  }
   590	  let event = @json.parse(line) catch { _ => Json::null() }
   591	  if field(event, "kind") == Some(Json::string("status")) {
   592	    if field(event, "state") == Some(Json::string("failed")) &&
   593	      field(event, "error") is Some(error) {
   594	      for name in ["message", "hint"] {
   595	        if field(error, name) is Some(Json::String(text)) {
   596	          self.message(
   597	            text,
   598	            debug=false,
   599	            warning=true,
   600	            emit=messages || statuses,
   601	          )
   602	        }
   603	      }
   604	      self.remember_unrecognized_json(event)
   605	    }
   606	    if statuses || messages {
   607	      self.status(event)
   608	    }
   609	    return
   610	  }
   611	  // Result envelopes and arbitrary structured responses are never log text.
   612	  if field(event, "kind") == Some(Json::string("result")) {
   613	    if field(event, "outcome") != Some(Json::string("success")) &&
   614	      (
