1417	///|
1418	async fn DiagnosticCapture::read(
1419	  self : DiagnosticCapture,
1420	  reader : @process.ReadFromProcess,
1421	) -> Unit {
1422	  try {
1423	    while reader.read_some(max_len=4096) is Some(chunk) {
1424	      let remaining = self.limit - self.output.length()
1425	      let count = if chunk.length() < remaining {
1426	        chunk.length()
1427	      } else {
1428	        remaining
1429	      }
1430	      if count > 0 {
1431	        self.output.write_bytes(chunk[:count])
1432	      }
1433	      if count < chunk.length() {
1434	        self.truncated = true
1435	      }
1436	    }
1437	  } catch {
1438	    error =>
1439	      if @async.is_being_cancelled() {
1440	        raise error
1441	      } else {
1442	        self.truncated = true
1443	      }
1444	  }
1445	  self.finished = true
1446	}
