1459	///|
1460	async fn diagnostic_process_output(
1461	  program : String,
1462	  args : Array[String],
1463	  environment~ : Map[String, String],
1464	  cwd? : StringView,
1465	  stdin? : &@process.ProcessInput,
1466	  stdout_limit~ : Int32,
1467	  stderr_limit~ : Int32,
1468	) -> (Int32, Bytes, Bool, Bytes, Bool) {
1469	  let (out, stdout) = @process.read_from_process()
1470	  defer out.close()
1471	  let (err, stderr) = @process.read_from_process()
1472	  defer err.close()
1473	  @async.with_task_group(async fn(group) {
1474	    let child = @process.spawn(
1475	      group,
1476	      program,
1477	      args,
1478	      extra_env=environment,
1479	      inherit_env=false,
1480	      cwd?,
1481	      stdin?,
1482	      stdout~,
1483	      stderr~,
1484	    )
1485	    let output = DiagnosticCapture::new(stdout_limit)
1486	    let errors = DiagnosticCapture::new(stderr_limit)
1487	    group.spawn_bg(no_wait=true, async fn() { output.read(out) })
1488	    group.spawn_bg(no_wait=true, async fn() { errors.read(err) })
1489	    let status = child.wait()
1490	    if status == 0 {
1491	      while !output.finished {
1492	        @async.sleep(5)
1493	      }
1494	      wait_diagnostic_captures([errors])
1495	    } else {
1496	      wait_diagnostic_captures([output, errors])
1497	    }
1498	    (
1499	      status,
1500	      output.output.to_bytes(),
1501	      output.truncated || !output.finished,
1502	      errors.output.to_bytes(),
1503	      errors.truncated || !errors.finished,
1504	    )
1505	  })
1506	}
