1085	    AdapterError(detail) => (detail, false)
1086	    InvalidConfig(detail) => (detail, false)
1087	    @base64.Malformed(_) => ("Malformed base64 input; input omitted", true)
1088	    @utf8.Malformed(_) => ("Malformed UTF-8 input; input omitted", true)
1089	    @json.InvalidNumber(position, _) =>
