1099	///|
1100	fn diagnostic_text(
1101	  message : String,
1102	  environment? : Map[String, String],
1103	  omitted~ : Bool = false,
1104	  protected_secrets? : Array[String],
1105	  incomplete_final_line~ : Bool = false,
1106	) -> String {
1107	  let progress = Progress::new("diagnostic-error", environment?)
1108	  if protected_secrets is Some(values) {
1109	    for value in values {
1110	      add_protected_secret(progress.secrets, value)
1111	    }
1112	  }
1113	  progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
1114	  let lines = []
1115	  let mut incomplete = omitted
1116	  let source_lines = message.split("\n").to_array()
1117	  for index in 0..<source_lines.length() {
1118	    let line = source_lines[index]
1119	    if lines.length() == 32 {
1120	      incomplete = true
1121	      ignore(lines.remove(1))
1122	    }
1123	    let truncated = line.length() > 1024
1124	    let bounded = if truncated {
1125	      incomplete = true
1126	      line[:1024].to_owned()
1127	    } else {
1128	      line.to_owned()
1129	    }
1130	    let bounded = if truncated ||
1131	      (incomplete_final_line && index == source_lines.length() - 1) {
1132	      diagnostic_partial_secret(bounded, progress.secrets)
1133	    } else {
1134	      bounded
1135	    }
1136	    match progress.safe_message(bounded) {
1137	      Some(safe) => lines.push(safe)
1138	      None => {
1139	        incomplete = true
1140	        lines.push("[unavailable]")
1141	      }
1142	    }
1143	  }
1144	  if (incomplete || progress.details_truncated) &&
1145	    lines.last() != Some("[error details incomplete or truncated]") {
1146	    lines.push("[error details incomplete or truncated]")
1147	  }
1148	  lines.join("\n")
1149	}
