390	async fn Progress::message(
391	  self : Progress,
392	  text : String,
393	  debug~ : Bool,
394	  warning~ : Bool,
395	  emit~ : Bool = true,
396	) -> Unit {
397	  if self.protection_incomplete {
398	    self.details_truncated = true
399	    self.remember(
400	      "error detail unavailable because workspace protection values could not be read",
401	      warning=true,
402	    )
403	    return
404	  }
405	  for line in text.split("\n") {
406	    let text = line.trim().to_owned()
407	    if text == "" {
408	      continue
409	    }
410	    guard self.safe_message(text) is Some(safe) else {
411	      self.details_truncated = true
412	      continue
413	    }
414	    if !debug || warning {
415	      self.remember(safe, warning~)
416	    }
417	    if !emit {
418	      continue
419	    }
420	    if safe.has_prefix("#") {
421	      guard safe.split_once(" ") is Some((id, rest)) &&
422	        id.length() > 1 &&
423	        id[1:].iter().all(c => c >= '0' && c <= '9') else {
424	        continue
425	      }
426	      let detail = rest.trim().to_owned()
427	      guard detail.has_prefix("[") ||
428	        detail.has_prefix("DONE") ||
429	        detail.has_prefix("ERROR") ||
430	        detail.has_prefix("CACHED") else {
431	        continue
432	      }
433	      if detail.has_prefix("ERROR") && debug && !warning {
434	        self.remember(safe, warning=true)
435	      }
436	      if self.builds.get(id.to_owned()) == Some(detail) {
437	        continue
438	      }
439	      if self.builds.length() < 2048 || self.builds.contains(id.to_owned()) {
440	        self.builds.set(id.to_owned(), detail)
441	      }
442	      progress_message("Build " + id.to_owned() + ": " + detail)
443	    } else if classic_build_step(safe) {
444	      // Classic RUN output has no prefix. Only its own completion marker
445	      // ends this mode; phase events on another pipe can arrive ahead of it.
446	      self.classic_build = true
447	      progress_message("Build " + safe)
448	    } else if safe.has_prefix("Successfully built ") ||
449	      safe.has_prefix("Successfully tagged ") {
450	      self.classic_build = false
451	      progress_message("Build: " + safe)
452	    } else if self.classic_build && !warning {
453	      continue
454	    } else if !debug && !safe.has_prefix("{") && !safe.has_prefix("[") {
455	      progress_message(self.stage + ": " + safe)
456	    } else if !debug && safe.has_prefix("[credential") {
457	      progress_message(self.stage + ": " + safe)
458	    }
459	  }
460	}
