505	///|
720	async fn Progress::read_output(
721	  self : Progress,
722	  reader : @process.ReadFromProcess,
723	  capture~ : Bool,
724	  statuses~ : Bool = false,
725	  messages~ : Bool = false,
726	  raw_messages~ : Bool = false,
727	) -> String {
728	  let output = @buffer.Buffer(size_hint=4096)
729	  let pending = @buffer.Buffer(size_hint=4096)
730	  let private_key : Ref[Bool] = { val: false, }
731	  let blocked : Ref[Bool] = { val: false, }
732	  let mut oversized = false
733	  let mut tail = ""
734	  while reader.read_some(max_len=4096) is Some(chunk) {
735	    if capture {
736	      output.write_bytes(chunk)
737	    } else {
738	      tail += @utf8.decode_lossy(chunk)
739	      if tail.length() > 8192 {
740	        tail = tail[tail.length() - 8192:].to_owned()
741	      }
742	    }
743	    for byte in chunk {
744	      if byte == b'\n' || byte == b'\r' {
745	        if !oversized && pending.length() > 0 {
746	          let line = @utf8.decode(pending.to_bytes()) catch {
747	            _ => {
748	              self.details_truncated = true
749	              blocked.val = true
750	              ""
751	            }
752	          }
753	          if self.filter_output_line(line, private_key, blocked) is Some(safe) {
754	            if raw_messages {
755	              self.message(safe, debug=false, warning=true, emit=false)
756	            } else if capture {
757	              self.line(safe, statuses~, messages~)
758	            } else {
759	              self.stderr_line(safe, statuses~, messages~)
760	            }
761	          }
762	        }
763	        pending.reset()
764	        oversized = false
765	      } else if !oversized {
766	        if pending.length() == 65536 {
767	          pending.reset()
768	          oversized = true
769	          blocked.val = true
770	          self.details_truncated = true
771	        } else {
772	          pending.write_byte(byte)
773	        }
774	      }
775	    }
776	  }
777	  if !oversized && pending.length() > 0 {
778	    let line = @utf8.decode(pending.to_bytes()) catch {
779	      _ => {
780	        self.details_truncated = true
781	        blocked.val = true
782	        ""
783	      }
784	    }
785	    let masked = diagnostic_partial_secret(line, self.secrets)
786	    if masked != line {
787	      self.details_truncated = true
788	    }
789	    if self.filter_output_line(masked, private_key, blocked) is Some(safe) {
790	      if raw_messages {
791	        self.message(safe, debug=false, warning=true, emit=false)
792	      } else if capture {
793	        self.line(safe, statuses~, messages~)
794	      } else {
795	        self.stderr_line(safe, statuses~, messages~)
796	      }
797	    }
798	  }
799	  if capture {
800	    @utf8.decode(output.to_bytes())
801	  } else {
802	    tail
803	  }
804	}

