303	fn diagnostic_json(
304	  value : Json,
305	  environment : Map[String, String],
306	  protected_secrets : Array[String],
307	  truncated : Ref[Bool],
308	  depth : Int32,
309	  stable_activity~ : Bool = false,
310	  secret_states~ : Bool = false,
311	  stable_operation~ : Bool = false,
312	  stable_arguments~ : Bool = false,
313	  parent~ : String = "",
314	) -> Json {
315	  if depth >= 64 {
316	    truncated.val = true
317	    return Json::string("[nested evidence omitted]")
318	  }
319	  match value {
320	    Json::Object(values) => {
321	      let result = Json::empty_object()
322	      for name, item in values {
323	        let key = name.to_lower().replace_all(old="_", new="")
324	        let safe_name = if (
325	            stable_arguments &&
326	            [
327	              "arguments", "value", "source", "argumentCount", "reason", "home",
328	              "context", "state", "effectiveContext",
329	            ].contains(name)
330	          ) ||
331	          (
332	            stable_operation &&
333	            depth == 0 &&
334	            ["operationId", "workspaceId"].contains(name)
335	          ) ||
336	          (
337	            stable_activity &&
338	            [
339	              "schemaVersion", "observedAt", "activity", "reason", "terminals", "chats",
340	              "errors", "worktreeId", "agent", "type", "state", "programState", "sessionId",
341	              "workspaceId", "source", "code", "id", "uid", "context", "provider",
342	              "identityVerified", "vmStatus", "outcome", "evidence", "evidenceTruncated",
343	              "workspaces", "discoveryErrors", "action", "failed", "detailsTruncated",
344	              "error", "autoStop", "orcaVersion", "handle", "connected", "foregroundProcess",
345	              "hasChildProcesses", "processEvidence", "verdict", "capturedAgeMs",
346	              "ptyIncarnationId", "observationEpoch", "stateStartedAt", "updatedAt",
347	              "working", "queuedMessages", "actionablePrompts", "backgroundTasks",
348	            ].contains(name)
349	          ) {
350	          name
351	        } else {
352	          diagnostic_text(name, environment~, protected_secrets~)
353	        }
354	        if field(result, safe_name) is Some(_) {
355	          truncated.val = true
356	          continue
357	        }
358	        if safe_name.has_suffix("\n[error details incomplete or truncated]") {
359	          truncated.val = true
360	        }
361	        set_field(
362	          result,
363	          safe_name,
364	          if credential_field(name, for_diagnostics=true) ||
365	            key == "pairingcode" {
366	            if secret_states &&
367	              field(item, "state") is Some(Json::String(state)) &&
368	              ["unset", "empty", "set"].contains(state) {
369	              let masked : Json = { "state": state }
370	              if field(item, "value") is Some(_) {
371	                set_field(masked, "value", Json::string("[redacted]"))
372	              }
373	              if field(item, "truncated") == Some(Json::boolean(true)) {
374	                set_field(masked, "truncated", Json::boolean(true))
375	                truncated.val = true
376	              }
377	              masked
378	            } else {
379	              Json::string("[redacted]")
380	            }
381	          } else if stable_activity &&
382	            name == "activity" &&
383	            (
384	              item == Json::string("idle") ||
385	              item == Json::string("active") ||
386	              item == Json::string("unknown")
387	            ) {
388	            item
389	          } else if stable_activity &&
390	            parent == "agent" &&
391	            item is Json::String(text) &&
392	            (
393	              (
394	                name == "state" &&
395	                ["working", "waiting", "blocked", "monitoring", "done"].contains(
396	                  text,
397	                )
398	              ) ||
399	              (
400	                name == "programState" &&
401	                ["working", "blocked", "idle"].contains(text)
402	              )
403	            ) {
404	            item
405	          } else {
406	            diagnostic_json(
407	              item,
408	              environment,
409	              protected_secrets,
410	              truncated,
411	              depth + 1,
412	              stable_activity~,
413	              secret_states~,
414	              stable_operation~,
415	              stable_arguments~,
416	              parent=name,
417	            )
418	          },
419	        )
420	      }
421	      result
422	    }
423	    Json::Array(values) =>
424	      Json::array(
425	        values.map(item => {
426	          diagnostic_json(
427	            item,
428	            environment,
429	            protected_secrets,
430	            truncated,
431	            depth + 1,
432	            stable_activity~,
433	            secret_states~,
434	            stable_operation~,
435	            stable_arguments~,
436	            parent~,
437	          )
438	        }),
439	      )
440	    Json::String(text) => {
441	      let safe = diagnostic_text(text, environment~, protected_secrets~)
442	      if safe.has_suffix("\n[error details incomplete or truncated]") {
443	        truncated.val = true
444	      }
445	      Json::string(safe)
446	    }
447	    _ => value
448	  }
449	}
