452	async fn diagnostic_retained_records(file : @fs.File, size : Int64) -> String {
453	  let length = if size > 262144L { 262144 } else { size.to_int() }
454	  let bytes = FixedArray::make(length, b'\x00')
455	  let read = file.read_at(bytes, position=size - length.to_int64())
456	  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
457	  let lines = text.split("\n").to_array()
458	  let kept = FixedArray::make(lines.length(), false)
459	  let mut remaining = 65536
460	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
461	    if i == 0 && size > length.to_int64() {
462	      continue
463	    }
464	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
465	    let overhead = if field(event, "runId") is Some(Json::String(_)) {
466	      100
467	    } else {
468	      0
469	    }
470	    let length = lines[i].length() + 1 + overhead
471	    if length <= remaining {
472	      kept[i] = true
473	      remaining -= length
474	    }
475	  }
476	  remaining = 65536
477	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
478	    if kept[i] || (i == 0 && size > length.to_int64()) {
479	      continue
480	    }
481	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
482	    let failed = field(event, "errorType") is Some(_) ||
483	      (match field(event, "status") {
484	        Some(Json::String(status)) =>
485	          ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
486	            status,
487	          )
488	        _ => false
489	      })
490	    let overhead = if field(event, "runId") is Some(Json::String(_)) {
491	      100
492	    } else {
493	      0
494	    }
495	    let length = lines[i].length() + 1 + overhead
496	    if failed && length <= remaining {
497	      kept[i] = true
498	      remaining -= length
499	    }
500	  }
501	  let dropped_runs : Map[String, Bool] = Map([])
502	  for i in 0..<(lines.length() - 1) {
503	    if !kept[i] {
504	      let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
505	      if field(event, "runId") is Some(Json::String(id)) {
506	        dropped_runs.set(id, true)
507	      }
508	    }
509	  }
510	  let result = @buffer.Buffer(size_hint=131072)
511	  for i in 0..<lines.length() {
512	    if kept[i] {
513	      let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
514	      if field(event, "runId") is Some(Json::String(id)) {
515	        set_field(
516	          event,
517	          "runCompleteness",
518	          Json::string(
519	            if dropped_runs.contains(id) ||
520	              field(event, "runCompleteness") == Some(Json::string("partial")) {
521	              "partial"
522	            } else {
523	              "unknown"
524	            },
525	          ),
526	        )
527	        set_field(event, "runMissingReason", Json::string("retention_limit"))
528	        result.write_string_utf8(event.stringify() + "\n")
529	      } else {
530	        result.write_string_utf8(lines[i].to_owned() + "\n")
531	      }
532	    }
533	  }
534	  @utf8.decode_lossy(result.to_bytes())
535	}
