134	  let directory = adapter_state_home()
135	  save_diagnostic("supervisor-launch", "restart", evidence={
136	    "stateDirectory": directory,
137	  })
138	  errdefer save_diagnostic(
139	    "supervisor-launch",
140	    "failed",
141	    error_type="restart_failed",
142	    evidence={ "stateDirectory": directory },
143	  )
144	  @fs.mkdir(directory, recursive=true, permission=0o700, allow_exist=true)
145	  let startup = @fs.open(
146	    directory + "/supervisor-startup.lock",
147	    mode=ReadWrite,
148	    create_mode=OpenOrCreate,
149	    permission=0o600,
150	  )
151	  defer startup.close()
152	  @async.with_timeout(30000, async fn() {
153	    while !startup.try_lock(Exclusive) {
154	      @async.sleep(10)
155	    }
156	    defer (@fs.remove(directory + "/shutdown") catch { _ => () })
157	    if supervisor_alive(directory) {
158	      @fs.write_file(directory + "/shutdown", "", permission=0o600)
159	      while supervisor_alive(directory) {
