166	    let failures : Ref[Int32] = { val: 0, }
167	    let transports = directory + "/transports"
168	    if @fs.exists(transports) {
169	      @async.with_task_group(async fn(group) {
170	        let permits = @async.Semaphore(16)
171	        for name in @fs.readdir(transports) {
172	          let transport = transports + "/" + name
173	          if @fs.exists(transport + "/state.json") &&
174	            !@fs.exists(transport + "/done") {
175	            permits.acquire()
176	            group.spawn_bg(async fn() {
177	              defer permits.release()
178	              let recording = transport_recording(transport)
179	              supervise_transport(transport, force=true) catch {
180	                error => {
181	                  failures.val += 1
182	                  save_diagnostic(
183	                    "supervisor-transport",
184	                    "failed",
185	                    error_type="transport_cleanup_failed",
186	                    error_message=diagnostic_error(error),
187	                    evidence={ "transport": transport },
188	                    recording~,
189	                  )
190	                  progress_message("SSH transport cleanup failed: " + transport)
191	                }
192	              }
193	            })
194	          }
195	        }
196	      })
197	    }
198	    launch_supervisor(directory)
199	    failures.val
200	  })
201	}
