607	///|
608	async fn supervisor_pending(
609	  directory : String,
610	  environments : Map[String, Map[String, String]],
611	) -> Bool {
612	  let base = directory + "/tunnels"
613	  if @fs.exists(base) {
614	    for name in @fs.readdir(base) {
615	      let workspace = base + "/" + name
616	      if environments.contains(@fs.realpath(workspace)) &&
617	        @fs.exists(workspace + "/enabled") &&
618	        @fs.exists(workspace + "/state.json") &&
619	        @fs.exists(workspace + "/request") {
620	        return true
621	      }
622	    }
623	  }
624	  let base = directory + "/transports"
625	  if @fs.exists(base) {
626	    for name in @fs.readdir(base) {
627	      if @fs.exists(base + "/" + name + "/state.json") &&
628	        !@fs.exists(base + "/" + name + "/done") {
629	        return true
630	      }
631	    }
632	  }
633	  false
634	}

